-- 09: 33 Kanwil dan seluruh UPT Pemasyarakatan (Lapas, Rutan, LPKA, Bapas) beserta titik peta,
-- serta pembeda lokasi kegiatan di dalam atau di luar UPT.
-- Sumber daftar: data induk UPT nasional (531 Lapas/Rutan/LPKA + 80 Bapas). Titik peta masih perkiraan
-- (pusat kabupaten/kota) dan ditandai titik_perkiraan = true sampai diverifikasi Administrator.

alter table public.master_kanwil add column if not exists wilayah text;
alter table public.master_kanwil add column if not exists tipe text check (tipe is null or tipe in ('A', 'B'));
alter table public.master_kanwil add column if not exists urutan int;
alter table public.master_kanwil add column if not exists provinsi text[];

alter table public.master_upt add column if not exists kelas text;
alter table public.master_upt add column if not exists kab_kota text;
alter table public.master_upt add column if not exists provinsi text;
alter table public.master_upt add column if not exists latitude numeric check (latitude is null or latitude between -11 and 7);
alter table public.master_upt add column if not exists longitude numeric check (longitude is null or longitude between 94 and 142);
alter table public.master_upt add column if not exists titik_perkiraan boolean not null default true;

alter table public.master_locations add column if not exists posisi text not null default 'Dalam UPT'
  check (posisi in ('Dalam UPT', 'Luar UPT'));
alter table public.master_locations add constraint master_locations_koordinat_ok
  check ((latitude is null or latitude between -11 and 7) and (longitude is null or longitude between 94 and 142));

